// Package genmarker emits generated-code marker lines for devtools generators.
package genmarker

// Pattern matches marker lines emitted by this package.
const Pattern = `^(//|#) Code generated .* DO NOT EDIT\.$`

// Line returns the standard marker line as a `//` comment, without a
// trailing newline:
//
//	// Code generated by <tool>; DO NOT EDIT.
func Line(tool string) string {
	return "// Code generated by " + tool + "; DO NOT EDIT."
}

// HashLine returns the marker line as a `#` comment for hash-comment
// languages (Python, shell, ...), without a trailing newline:
//
//	# Code generated by <tool>; DO NOT EDIT.
func HashLine(tool string) string {
	return "# Code generated by " + tool + "; DO NOT EDIT."
}

// DotLine returns the period-separated marker variant, without a trailing
// newline:
//
//	// Code generated by <tool>. DO NOT EDIT.
//
// The registry/table generators (tools/codegen, tools/go2rs_tables)
// historically emit this form; it is kept so their outputs stay
// byte-identical. New generators should use Line.
func DotLine(tool string) string {
	return "// Code generated by " + tool + ". DO NOT EDIT."
}
